            vals = json.loads(value)
            if not isinstance(vals, list) or len(vals) != len(self.fields):
                raise ValueError(
                    f"{self.name!r} must be a list of {len(self.fields)} elements."
                )
            value = [
                field.to_python(val)
                for field, val in zip(self.fields, vals, strict=True)
            ]
